  'Remove this passkey?': '確定要移除此通行密鑰？',
  'Scan this with the other device, or open Gains there and enter the code on the sign-in screen. It works once, for {0} minutes.': '使用另一台裝置掃描，或在該裝置開啟 Gains 並於登入畫面輸入代碼。此代碼僅能使用一次，有效時間為 {0} 分鐘。',
  'This browser cannot confirm with your passkey. Do this on a device that holds one.': '此瀏覽器無法使用通行密鑰驗證。請在存有金鑰的裝置上進行此操作。',
  'First confirm that it is you.': '請先確認是你本人。',
  'This profile has no passkey, and this server does not take passwords, so nothing here can confirm that it is you. Ask your admin.': '此個人檔案未設定通行密鑰，且伺服器不接受密碼驗證，因此無法確認身分。請洽詢管理員。',
  'This browser cannot create passkeys, so it cannot be added with a code. Open the link in a browser that can.': '此瀏覽器不支援建立通行密鑰，無法透過代碼新增。請改用支援的瀏覽器開啟此連結。',
  'This browser is signed in as “{0}”. Adding it to “{1}” signs “{0}” out here.': '此瀏覽器目前登入為「{0}」。綁定至「{1}」將會使「{0}」在此登出。',
  'This code is for a different profile that is also called “{0}”, not the one this browser is signed in as. Adding it there signs yours out here.': '此代碼屬於另一個同樣名為「{0}」的檔案，非此瀏覽器目前登入的帳號。綁定將導致你目前的帳號在此登出。',
  'Only continue if this code comes from a device of your own. This browser is then signed in to “{0}”, and what you log here goes to that profile.': '僅在代碼來自你擁有的裝置時才繼續。此瀏覽器將登入至「{0}」，後續所有訓練記錄將同步至該檔案。',
  'This code has expired.': '此代碼已過期。',
  'This device already has a passkey for this profile.': '此裝置已擁有該個人檔案的通行密鑰。',
  'This passkey already belongs to a profile.': '此通行密鑰已綁定至其他個人檔案。',
  'This profile already has as many passkeys as it can hold.': '此個人檔案持有的通行密鑰數量已達上限。',
  'Use a code from your other device': '使用來自另一台裝置的配對碼',
  'You get a code that lets your phone or another computer create a passkey for this profile. First confirm that it is you.': '系統將產生一組代碼，供你的手機或電腦為此檔案建立通行密鑰。請先確認你的身分。',
