  'No automatic progression': '不啟用自動進階',
  'The next regular target continues from the last included workout.': '下一個目標將直接延續上次採計的訓練數據。',
  'Deload routine': '減量訓練課表',
  'Its workouts do not count toward progression. They still show in history and statistics.': '此課表的訓練不計入漸進加重規則，但仍會保留於歷史與統計數據中。',
  'A deload routine opens at the numbers set here, so the progression above does not apply to it.': '減量課表將以此處設定的數值開始，不適用上述漸進超負荷規則。',
  'Linear progression': '線性進階 (Linear Progression)',
  'Greyskull LP': 'Greyskull LP 漸進法',
  'Double progression': '雙重漸進 (Double Progression)',
  'Add time': '增加時間',
  'Targets stay where you set them.': '目標將維持你所設定的固定值。',
  'Hit every rep in every set and the weight goes up. Repeated misses trigger a deload.': '每組皆達成指定次數即自動加重。若連續未達標將自動觸發減量機制。',
  'Two straight sets plus a final set taken to failure. Beat the target on that set and the weight goes up (twice as much if you double the reps). One failure resets 10 %.': '兩組固定組，再加最後一組做到力竭。最後一組突破目標就加重（次數翻倍則加倍）。失敗一次退回 10 %。',
  'Work up through a rep range at the same weight. Reach the top of the range in every set and the weight goes up, reps back to the bottom.': '在相同重量下逐漸拉高次數。每組皆能達到次數上限時即增加重量，並將次數回調至下限。',
  'Hold every set for the full duration and the target goes up.': '每組均能支撐達目標時間後，下次即自動提高時間目標。',
  'Nothing logged yet, so this session sets the baseline.': '還沒有紀錄，所以這次訓練就是基準線。',
  'Held every set for the full time. Target goes up by {0}s.': '每組都撐滿了時間。目標增加 {0} 秒。',
  'Short {0} sessions in a row. Back off to {1}s and build up again.': '連續 {0} 次沒撐滿。退回 {1} 秒，重新累積。',
  'Came up short last time. Same target again.': '上次差了一點。再挑戰一次相同目標。',
  'Top of the rep range in every set. {0} {1} more, back to {2} reps.': '每組都達到次數上限。加重 {0} {1}，次數回到 {2} 下。',
  'Stuck for {0} sessions. Deload to {1} {2}.': '已停滯 {0} 次訓練。減量至 {1} {2}。',
  'Same weight, aim for {0} reps this time.': '相同重量，這次目標 {0} 下。',
  'Last set hit {0} reps, twice the target! Take a double jump of {1} {2}.': '最後一組做了 {0} 下，是目標的兩倍！加倍提升 {1} {2}。',
  'Every rep last time. {0} {1} more.': '上次每一下都完成了。增加 {0} {1}。',
  'Every rep last time. {0} {1} less help.': '上次每一下都完成了。輔助減少 {0} {1}。',
  'Top of the rep range in every set. {0} {1} less help, back to {2} reps.': '每組都達到次數上限。輔助減少 {0} {1}，次數回到 {2} 下。',
  'Missed reps. {0} {1} of help while you build back up.': '次數未達標。先用 {0} {1} 輔助，慢慢練回來。',
  'Stuck for {0} sessions. Back to {1} {2} of help, then build up again.': '已停滯 {0} 次。退回 {1} {2} 輔助，再重新往上練。',
  'Missed reps {0} sessions running. Reset to {1} {2} and work back up.': '連續 {0} 次次數未達標。重設為 {1} {2}，重新往上練。',
  'Missed reps. Reset to {0} {1} and work back up.': '次數未達標。重設為 {0} {1}，重新往上練。',
  'Missed reps last time. Same weight again ({0} of {1} to go).': '上次次數未達標。再用相同重量（還剩 {0}/{1} 次）。',
  'Bodyweight: every rep last time, so go for {0} this time.': '徒手動作：上次每一下都完成了，這次挑戰 {0} 下。',
  'Bodyweight: same target again until every set is clean.': '徒手動作：維持相同目標，直到每一組都做得乾淨俐落。',

  // --- effort per set (RIR / RPE) ---
  '{0} sets bring an {1} with them. Switch on Effort per set in Settings to see it.': '{0} 組自帶 {1}。在設定中開啟「每組自覺強度」就能看到。',
  '{0} sets bring an {1} with them.': '{0} 組自帶 {1}。',
