  'RPE': 'RPE (自覺強度)',
  'Effort per set': '每組自覺強度',
  'What are RIR and RPE?': '什麼是 RIR 與 RPE？',
  'How hard a set was, logged next to weight and reps. Two scales for the same judgement, counted from opposite ends.': '記錄每組的自覺費力程度，與重量和次數並列。這是衡量同一感受的兩種量表，只是從相反方向評估。',
  'How it felt': '體感評估',
  'Nothing left, went to failure': '一滴不剩，做到力竭',
  'One more rep in the tank': '還能再做 1 下',
  'Two more reps': '還能再做 2 下',
  'Three more reps': '還能再做 3 下',
  'Easy, warm-up territory': '輕鬆，熱身強度',
  'Maybe half a rep left': '大概還能再拼半下',
  'How hard was that set?': '這組感覺有多吃力？',
  'Tap how many reps you had left, or type an exact {0}.': '點選你覺得還能做幾下，或直接輸入準確的 {0}。',
  'Exact {0}': '指定 {0} 數值',
  'Clear rating': '清除自覺評分',
  'RIR counts the reps you left in the tank; RPE reads the same effort off a 10-point scale, so RPE ≈ 10 − RIR. Pick whichever you already think in.': 'RIR 算的是你還留了幾下；RPE 則把同樣的吃力程度放到 10 分制來看，所以 RPE ≈ 10 − RIR。選你習慣的那種就好。',
  'The highlighted row is where most working sets land. Sets you have already logged keep their own scale, and nothing else reads the value, so progression and estimated 1RM are unaffected.': '醒目標示的那一列是大部分正式組的落點。已記錄的組保留原本的標度，其他地方也不會讀取這個值，所以漸進超負荷與預估 1RM 都不受影響。',
