  'Where the sets land': '組數落點分佈',
  'Most working sets belong close to failure, not at it. Half at the floor and half at the top still average out to a healthy-looking middle.': '大部分正式組應該接近力竭，而不是真的力竭。一半在最底、一半在最頂，平均起來照樣看起來很健康。',
