  'No weight to enter. Just log the reps.': '無需輸入重量。只要記錄次數就好。',
  'Ask for a weight on every set.': '每組皆詢問重量。',
  'For dips or pull-ups with a belt. Progression then follows the weight.': '適用於懸吊負重腰帶進行雙槓撐體或引體向上，此時漸進超負荷將依照負重計算。',
