  'Top of the range': '次數上限',
  'Reps climb by one whenever every set was clean. Set a ceiling to add sets instead of reps forever.': '每組皆順利完成時次數自動加一。設定上限後，達標時將增加組數而非無止境增加次數。',
  'Reps climb to {0}, then a set is added and the reps start over. At {1} sets it asks you to add weight instead.': '次數提高至 {0} 下後自動增加一組，次數回調至起點。達到 {1} 組時則會提示你該加重量了。',
