  'Your name, your sign-in details and everything else about your account stay here. Other people’s data is never included.': '你的姓名、登入資訊與其他個人帳號細節均保留在本機，絕不包含其他使用者的資料。',
  'You can turn this off at any time, which also discards anything the Coach is holding for you.': '你可以隨時停用此功能，這也會同時清除教練暫存的所有建議事項。',
  'The Coach is not a doctor or a physiotherapist. If something hurts, ask a professional.': 'AI 教練並非專業醫師或物理治療師。若感覺身體疼痛或不適，請向醫療專業人士諮詢。',
