  // --- AI Coach on the phone ---
  '(saved)': '（已儲存）',
  'AI Coach': 'AI 教練',
  'API key': 'API 金鑰',
  'An AI coach that can design your plan and adjust it from what you actually log. It runs with your own API key, it never changes anything without your say-so, and it is off until you turn it on.': '一個能為你規劃課表並依訓練紀錄給予回饋的 AI 教練。使用你自己的 API 金鑰在手機端運算，未經許可絕不變更課表，預設為關閉狀態。',
  'Bring my own API key': '使用我自備的 API 金鑰',
  'Could not reach the provider: {0}': '無法連線至服務提供商：{0}',
  'Android blocks unencrypted http:// connections from apps, so this phone can only reach an https:// endpoint. Put HTTPS in front of it (Tailscale or a reverse proxy), or choose “Use my self-hosted Gains”: your server can reach an http:// model on its own network.': 'Android 系統預設阻擋未加密的 http:// 連線，因此只能連線至 https:// 端點。請使用 HTTPS（例如透過 Tailscale 或反向代理），或者選擇「使用我自託管的 Gains」由伺服器在內網連線 http:// 模型。',
  'Each request goes straight to {0} with your key. Nobody else sees it, and you pay for it.': '每個請求都會帶著你的金鑰直接送到 {0}。其他人都看不到，費用由你支付。',
