  'When you ask for a plan or a review, this phone sends the following straight to {0}, using your own API key. You pay for every request.': '當你請求計畫或分析時，此手機將使用你的金鑰把下列資料發送至 {0}，每次呼叫費用均由你的帳號負擔。',
  'Your server has no Coach enabled. Ask its admin, or bring your own key below.': '你的伺服器沒有啟用教練。請聯繫管理員，或在下方使用自備的金鑰。',
  'Your server runs the Coach with whatever provider its admin set up. Nothing new leaves this phone beyond what already syncs.': '你的伺服器將透過管理員設定的服務商執行教練功能。除了原本已同步的數據外，不會有任何額外資料離開此手機。',
