  'Hi, I’m your Coach. I build your plan from your answers and adjust it from what you actually log. Nothing changes until you say so.': '嗨，我是你的教練。我會根據你的回答建立計畫，再依你實際記錄的內容調整。你沒點頭，什麼都不會變。',
  'I looked through everything and there is nothing I would change right now. Keep it up, and ask me again after a few more sessions.': '我全部看過一遍，目前沒有想改的地方。繼續保持，多練幾次後再來問我。',
