  'Sign in again, or export a backup first. Going ahead anyway keeps a copy of these changes on this device until it connects to this server as this account again. Then they’re added back.': '請重新登入，或先匯出備份。若仍要繼續，這些變更的副本會保留在此裝置上，直到它再次以此帳號連線到此伺服器。屆時會重新加回。',
