  'Add this device\'s plan to your profile?': '是否將此裝置上的計畫加入你的個人檔案？',
  'Your plan, notes or gym cards on this device were set up while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': '此裝置在未登入狀態下設定了計畫、備註或健身房卡。是否將其加入你的個人檔案，或是維持伺服器上的原本紀錄？',
  '{0} routine was made on this device while signed out. Add it to your profile, or keep the profile exactly as it is on the server.': '此裝置在未登入狀態下建立了 {0} 個訓練菜單。是否將其加入你的個人檔案，或是維持伺服器上的原本紀錄？',
  '{0} routines were made on this device while signed out. Add them to your profile, or keep the profile exactly as it is on the server.': '此裝置在未登入狀態下建立了 {0} 個訓練菜單。是否將其加入你的個人檔案，或是維持伺服器上的原本紀錄？',
  'This device, before signing in': '此裝置（登入前）',
  'This device, before the update': '此裝置（更新前）',
  'Signed in from another tab. Your workout came along, keep going here.': '已在另一個分頁登入。你的訓練也一起帶過去了，在這裡繼續吧。',
  'Plain http:// isn’t encrypted. Fine on your home network, but use https:// if your server is reachable from the internet.': '一般 http:// 沒有加密。在家用網路裡沒問題，但如果你的伺服器可以從網際網路連到，請用 https://。',
  'Could not reach {0} over https://. If your server runs on plain http (common at home), type http://{0} instead.': '無法透過 https:// 連到 {0}。如果你的伺服器使用一般 http（在家裡很常見），請改輸入 http://{0}。',
  'e.g. “swap the squats for split squats, and Mondays are short”': '例如「把深蹲換成保加利亞分腿蹲，週一練短一點」',
  'Added before your work sets and left out of volume, records and progression. Each one closes half the gap to the work weight, and you can still change any of them mid-session.': '在正式組之前加入，不計入訓練量、紀錄與漸進規則。每一組會縮短一半與正式重量的差距，訓練中也能隨時修改。',
  'The app can only pair with an https:// address. Your phone blocks plain http:// before anything is even sent.': 'App 只能與 https:// 位址配對。純 http:// 在傳送任何東西之前就會被手機擋下。',
  'Sounds': '音效',
